var C = class {
	_view = null;
	_languageCompartment = null;
	_editableCompartment = null;
	_onDirtyChange;
	_isDirty = false;
	async initialize(o, f = "", p = "text/turtle", m = "dark", h) {
		this._view && this._view.destroy(), this._languageCompartment = new Compartment(), this._editableCompartment = new Compartment(), this._onDirtyChange = h, this._isDirty = false;
		let g = await this._getLanguageExtension(p), _ = EditorState.create({
			doc: f,
			extensions: [
				m === "dark" ? vscodeDark : vscodeLight,
				EditorView.theme({ "&": { minHeight: "6lh" } }),
				this._languageCompartment.of(g),
				this._editableCompartment.of(EditorView.editable.of(true)),
				syntaxHighlighting(defaultHighlightStyle, { fallback: true }),
				lineNumbers(),
				history(),
				drawSelection(),
				EditorView.lineWrapping,
				EditorView.updateListener.of((e) => {
					e.docChanged && !this._isDirty && (this._isDirty = true, this._onDirtyChange?.(true));
				}),
				keymap.of([...defaultKeymap, ...historyKeymap])
			]
		});
		this._view = new EditorView({
			state: _,
			parent: o
		});
	}
	destroy() {
		this._view?.destroy(), this._view = null, this._isDirty = false;
	}
	getValue() {
		return this._view ? this._view.state.doc.toString() : "";
	}
	replaceContent(e) {
		this._view && this._view.state.doc.toString() !== e && this._view.dispatch({ changes: {
			from: 0,
			to: this._view.state.doc.length,
			insert: e
		} });
	}
	resetDirtyState() {
		this._isDirty = false;
	}
	setReadOnly(e) {
		if (!this._view) return;
		let t = this._editableCompartment;
		t && this._view.dispatch({ effects: t.reconfigure(EditorView.editable.of(!e)) });
	}
	focusEditor() {
		this._view?.focus();
	}
	async setLanguage(e) {
		if (!this._view) return;
		let t = this._languageCompartment;
		if (!t) return;
		let n = await this._getLanguageExtension(e);
		this._view.dispatch({ effects: t.reconfigure(n) });
	}
	async _getLanguageExtension(e) {
		switch (e) {
			case "text/turtle":
			case "text/n3": return StreamLanguage.define(turtle);
			case "application/sparql-update":
			case "application/sparql-query": return StreamLanguage.define(sparql);
			case "application/nquads":
			case "application/n-quads":
			case "application/n-triples": return StreamLanguage.define(ntriples);
			case "application/json":
			case "application/ld+json": return json();
			case "text/html":
			case "application/xhtml+xml": return html();
			case "text/markdown":
			case "text/x-markdown":
			case "text/md": return markdown();
			case "application/rdf+xml":
			case "application/xml": return xml();
			case "text/css": return css();
			case "text/javascript":
			case "application/javascript":
			case "application/ecmascript": return javascript();
			default: return [];
		}
	}
};

